import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  customType,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Phase 0 schema (plan, section 6). Conventions for every table (ADR 0006):
// UUIDv7 ids generated by PostgreSQL 18, timestamptz, user_id on every per-user table.

const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});

const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);
const at = (name: string) => timestamp(name, { withTimezone: true });
const createdAt = () => at('created_at').notNull().defaultNow();

export const users = pgTable(
  'user',
  {
    id: id(),
    email: text('email').notNull(),
    displayName: text('display_name').notNull(),
    role: text('role').notNull().default('owner'),
    locale: text('locale').notNull().default('fr-BE'),
    timeZone: text('time_zone').notNull().default('Europe/Brussels'),
    webauthnUserHandle: bytea('webauthn_user_handle').notNull(),
    passwordHash: text('password_hash'),
    passwordFallbackEnabled: boolean('password_fallback_enabled').notNull().default(true),
    status: text('status').notNull().default('active'),
    createdAt: createdAt(),
    updatedAt: at('updated_at').notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('user_email_lower_idx').on(sql`lower(${t.email})`),
    uniqueIndex('user_webauthn_user_handle_idx').on(t.webauthnUserHandle),
    check('user_role_check', sql`${t.role} in ('owner', 'member')`),
    check('user_status_check', sql`${t.status} in ('active', 'disabled')`),
  ],
);

export const passkeys = pgTable(
  'passkey',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    credentialId: text('credential_id').notNull(),
    publicKey: bytea('public_key').notNull(),
    signCount: bigint('sign_count', { mode: 'number' }).notNull().default(0),
    transports: text('transports')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    aaguid: uuid('aaguid'),
    deviceType: text('device_type').notNull(),
    backedUp: boolean('backed_up').notNull().default(false),
    name: text('name').notNull(),
    createdAt: createdAt(),
    lastUsedAt: at('last_used_at'),
  },
  (t) => [
    uniqueIndex('passkey_credential_id_idx').on(t.credentialId),
    index('passkey_user_id_idx').on(t.userId),
    check('passkey_device_type_check', sql`${t.deviceType} in ('singleDevice', 'multiDevice')`),
  ],
);

export const sessions = pgTable(
  'session',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: bytea('token_hash').notNull(),
    authMethod: text('auth_method').notNull(),
    createdAt: createdAt(),
    lastSeenAt: at('last_seen_at').notNull().defaultNow(),
    idleExpiresAt: at('idle_expires_at').notNull(),
    absoluteExpiresAt: at('absolute_expires_at').notNull(),
    reauthenticatedAt: at('reauthenticated_at').notNull(),
    userAgentLabel: text('user_agent_label'),
    revokedAt: at('revoked_at'),
  },
  (t) => [
    uniqueIndex('session_token_hash_idx').on(t.tokenHash),
    index('session_user_id_idx').on(t.userId),
    check(
      'session_auth_method_check',
      sql`${t.authMethod} in ('passkey', 'password_totp', 'password_recovery')`,
    ),
  ],
);

export const authChallenges = pgTable(
  'auth_challenge',
  {
    id: id(),
    purpose: text('purpose').notNull(),
    challenge: text('challenge'),
    bindingHash: bytea('binding_hash').notNull(),
    userId: uuid('user_id').references(() => users.id, { onDelete: 'cascade' }),
    expiresAt: at('expires_at').notNull(),
    consumedAt: at('consumed_at'),
    createdAt: createdAt(),
  },
  (t) => [
    index('auth_challenge_binding_idx').on(t.bindingHash, t.purpose),
    check(
      'auth_challenge_purpose_check',
      sql`${t.purpose} in ('registration', 'authentication', 'reauth', 'password_verified')`,
    ),
  ],
);

export const oneTimeTokens = pgTable(
  'one_time_token',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    purpose: text('purpose').notNull(),
    tokenHash: bytea('token_hash').notNull(),
    expiresAt: at('expires_at').notNull(),
    consumedAt: at('consumed_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('one_time_token_hash_idx').on(t.tokenHash),
    index('one_time_token_user_id_idx').on(t.userId),
    check('one_time_token_purpose_check', sql`${t.purpose} in ('enrollment')`),
  ],
);

// The active secret stays usable while a replacement waits for confirmation (pending_*).
export const totpSecrets = pgTable('totp_secret', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  secretCiphertext: bytea('secret_ciphertext'),
  keyVersion: integer('key_version').notNull().default(1),
  confirmedAt: at('confirmed_at'),
  lastUsedStep: bigint('last_used_step', { mode: 'number' }),
  pendingSecretCiphertext: bytea('pending_secret_ciphertext'),
  pendingCreatedAt: at('pending_created_at'),
  createdAt: createdAt(),
});

export const recoveryCodes = pgTable(
  'recovery_code',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    batchId: uuid('batch_id').notNull(),
    codeHmac: bytea('code_hmac').notNull(),
    usedAt: at('used_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('recovery_code_user_hmac_idx').on(t.userId, t.codeHmac),
    index('recovery_code_user_id_idx').on(t.userId),
  ],
);

export const authThrottles = pgTable(
  'auth_throttle',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    factor: text('factor').notNull(),
    failures: integer('failures').notNull().default(0),
    lockedUntil: at('locked_until'),
    lastFailureAt: at('last_failure_at'),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.factor] }),
    check('auth_throttle_factor_check', sql`${t.factor} in ('password', 'totp', 'recovery')`),
  ],
);

export const pushSubscriptions = pgTable(
  'push_subscription',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    endpoint: text('endpoint').notNull(),
    p256dh: text('p256dh').notNull(),
    auth: text('auth').notNull(),
    userAgentLabel: text('user_agent_label'),
    createdAt: createdAt(),
    lastSuccessAt: at('last_success_at'),
  },
  (t) => [
    uniqueIndex('push_subscription_endpoint_idx').on(t.endpoint),
    index('push_subscription_user_id_idx').on(t.userId),
  ],
);

export const auditLog = pgTable(
  'audit_log',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    occurredAt: at('occurred_at').notNull().defaultNow(),
    actorType: text('actor_type').notNull(),
    // No foreign key: the log outlives a deleted account and is never updated.
    actorUserId: uuid('actor_user_id'),
    action: text('action').notNull(),
    outcome: text('outcome').notNull(),
    targetType: text('target_type'),
    targetId: text('target_id'),
    requestId: text('request_id'),
    metadata: jsonb('metadata')
      .$type<Record<string, unknown>>()
      .notNull()
      .default(sql`'{}'::jsonb`),
  },
  (t) => [
    index('audit_log_actor_idx').on(t.actorUserId, t.occurredAt),
    check('audit_log_actor_type_check', sql`${t.actorType} in ('user', 'cli', 'system')`),
    check('audit_log_outcome_check', sql`${t.outcome} in ('success', 'failure', 'denied')`),
  ],
);

export type User = typeof users.$inferSelect;
export type Passkey = typeof passkeys.$inferSelect;
export type Session = typeof sessions.$inferSelect;
export type AuthChallenge = typeof authChallenges.$inferSelect;
export type AuditEntry = typeof auditLog.$inferSelect;
export type PushSubscription = typeof pushSubscriptions.$inferSelect;

// Phase 1 profile tables (row-level security, ADR 0011).
export * from './profile-schema';

// Phase 1 imports: uploaded files and their extraction (ADR 0010).
export * from './import-schema';

// Phase 1 AI: call log, import proposals, keyword runs (ADR 0009).
export * from './ai-schema';
